<script setup lang="ts">
import { computed, ref } from 'vue';
import { useRoute } from 'vue-router';
import { errorText, post, validPassword } from '../saas';
import SaasPublicFrame from '../components/SaasPublicFrame.vue';
const route=useRoute();const token=computed(()=>String(route.query.token??''));const password=ref('');const confirmation=ref('');const loading=ref(false);const error=ref('');const activated=ref('');
async function submit(){error.value='';if(!token.value){error.value='激活链接缺少凭证，请联系省级管理员重新生成邀请';return}if(!validPassword(password.value)){error.value='密码至少8位，并包含大写字母、小写字母、数字和符号';return}if(password.value!==confirmation.value){error.value='两次输入的密码不一致';return}loading.value=true;try{const r=await post('/saas/activate',{token:token.value,password:password.value});activated.value=r.username;password.value='';confirmation.value=''}catch(e){error.value=errorText(e)}finally{loading.value=false}}
</script>
<template><SaasPublicFrame narrow><template v-if="activated"><el-result icon="success" title="管理员账号已激活" :sub-title="`登录账号：${activated}`"><template #extra><router-link to="/login"><el-button type="primary">前往登录</el-button></router-link></template></el-result></template><template v-else><h1>激活管理员账号</h1><p class="intro">设置登录密码后，即可通过统一入口进入所属城市。</p><el-alert v-if="!token" title="激活链接不完整，请联系省级管理员重新生成邀请。" type="warning" :closable="false"/><el-form label-position="top" @submit.prevent="submit"><el-form-item label="登录密码" required><el-input v-model="password" type="password" show-password autocomplete="new-password" aria-label="登录密码"/></el-form-item><p class="saas-subtle">至少8位，包含大写字母、小写字母、数字和符号。</p><el-form-item label="确认密码" required><el-input v-model="confirmation" type="password" show-password autocomplete="new-password" aria-label="确认密码"/></el-form-item><div v-if="error" class="saas-error" role="alert"><span>{{error}}</span></div><footer class="saas-public-footer"><span class="saas-subtle">邀请仅可使用一次。</span><el-button native-type="submit" type="primary" :disabled="!token" :loading="loading">激活账号</el-button></footer></el-form></template></SaasPublicFrame></template>
